// Before: nested checks and casts
string Describe(object o)
{
    if (o is null) return "nothing";
    if (o is string s) return $"string: {s}";
    if (o is int i && i > 0) return $"positive int: {i}";
    if (o is int) return "non-positive int";
    return "other";
}

// After: one exhaustive expression — order matters (specific first)
string Describe(object? o) => o switch
{
    null => "nothing",
    string { Length: 0 } => "empty string",
    string s => $"string: {s}",
    > 0 and int i => $"positive int: {i}",      // relational + type + binding
    int => "non-positive int",
    _ => "other"
};

// Sealed hierarchy: add Triangle and the compiler flags every incomplete switch
public abstract record Shape;
public record Circle(double R) : Shape;
public record Square(double Side) : Shape;

static double Area(Shape s) => s switch
{
    Circle { R: var r } => Math.PI * r * r,      // property + var binding
    Square sq           => sq.Side * sq.Side,
    // no '_' — compiler enforces exhaustiveness for the sealed hierarchy
};

// Property patterns for filtering — no helper extension methods needed
var prodErrors = logs.Where(e => e is { Level: "error", Service: "billing" and not "billing-canary" });

// Relational + and/or/not
string Classify(int score) => score switch
{
    >= 90 and not 100 => "A",
    100               => "A+",
    >= 70 and < 90    => "B",
    _                 => "needs work"
};

// Statement switch with a guard
switch (request)
{
    case { Method: "GET", Path: var p } when p.StartsWith("/api"):
        return HandleApiGet(p);
    case HttpRequest:
        return HandleOther();
}

